import{_ as a,o as r,c as i,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"पर्यावरण संरक्षण कानून","description":"","frontmatter":{},"headers":[],"relativePath":"hi/46-环境保护法.md","filePath":"hi/46-环境保护法.md","lastUpdated":null}'),e={name:"hi/46-环境保护法.md"};function d(o,t,h,n,s,b){return r(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="पर्यावरण-संरक्षण-कानून" tabindex="-1">पर्यावरण संरक्षण कानून <a class="header-anchor" href="#पर्यावरण-संरक्षण-कानून" aria-label="Permalink to &quot;पर्यावरण संरक्षण कानून&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>46</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>पर्यावरण संरक्षण, ब्रह्मांड-मूल, पारिस्थितिक सहजीवन, सतत विकास, प्रदूषण-रोकथाम</td></tr></tbody></table><h2 id="i-विधायी-उद्देश्य-और-मूल-सिद्धांत" tabindex="-1">I. विधायी उद्देश्य और मूल सिद्धांत <a class="header-anchor" href="#i-विधायी-उद्देश्य-और-मूल-सिद्धांत" aria-label="Permalink to &quot;I. विधायी उद्देश्य और मूल सिद्धांत&quot;">​</a></h2><p><em>पर्यावरण संरक्षण कानून</em> लंगर सहजीवी सभ्यता के पाँच सहायक कानूनों में से एक है। इसका उद्देश्य हेंग-ब्रह्मांड के भीतर पारिस्थितिक पर्यावरण और ब्रह्मांड-मूल की रक्षा, &quot;सहजीवी विकास, सतत विकास&quot; की पर्यावरण-शासन दर्शन स्थापित करना, शिकारी विकास द्वारा ब्रह्मांडीय पारिस्थितिकी-तंत्र के विनाश को रोकना और दस हजार जातियों के साझा उन्नयन के लिए जीवन-नींव की रक्षा करना है।</p><p>यह कानून निम्न मूल सिद्धांत स्थापित करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>मूल-संरक्षण</td><td>ब्रह्मांड-मूल सभी जीवन और विकास की नींव है; प्राथमिकता से संरक्षित होना चाहिए; विनाशकारी दोहन निषिद्ध</td></tr><tr><td>पारिस्थितिक सहजीवन</td><td>मानव और प्रकृति, सभी जातियाँ और पारिस्थितिकी-तंत्र सहजीवी संबंध में हैं; पारिस्थितिकी को नष्ट करना अपनी जीवन-नींव को नष्ट करना है</td></tr><tr><td>स्थिरता</td><td>सभी विकास-गतिविधियों को वर्तमान और भावी पीढ़ियों के हितों का ध्यान रखना चाहिए; सब कुछ निचोड़ लेने का विरोध</td></tr><tr><td>रोकथाम-प्राथमिकता</td><td>पर्यावरण संरक्षण रोकथाम-उन्मुख है; प्रदूषण रोकने हेतु पर्यावरणीय प्रभाव मूल्यांकन व्यवस्था स्थापित</td></tr><tr><td>प्रदूषक-दायित्व</td><td>पर्यावरण-प्रदूषण और पारिस्थितिकी-विनाश करने वाले विषयों को उपचार और क्षतिपूर्ति-दायित्व वहन करना होगा</td></tr><tr><td>जन-भागीदारी</td><td>पर्यावरण संरक्षण में जन-भागीदारी को प्रोत्साहन; जनता के पर्यावरणीय जानकारी-अधिकार और भागीदारी-अधिकार की गारंटी</td></tr><tr><td>अंतर-पटल समन्वय</td><td>पर्यावरण संरक्षण पटलों के बीच समन्वित रूप से आगे बढ़ता है; अंतर-पटल पर्यावरण-शासन सहयोग तंत्र स्थापित</td></tr></tbody></table><h2 id="ii-पर्यावरण-संरक्षण-की-सीमा" tabindex="-1">II. पर्यावरण संरक्षण की सीमा <a class="header-anchor" href="#ii-पर्यावरण-संरक्षण-की-सीमा" aria-label="Permalink to &quot;II. पर्यावरण संरक्षण की सीमा&quot;">​</a></h2><p>इस कानून द्वारा संरक्षित पर्यावरण-सीमा में हेंग-ब्रह्मांड के भीतर सभी पारिस्थितिकी-तंत्र और पर्यावरण-तत्व शामिल हैं:</p><ol><li><strong>वायुमंडलीय पर्यावरण</strong>: प्रत्येक ग्रह के वायुमंडल और ऊर्जा-परतों की ऊर्जा-सांद्रता और घटक-संतुलन शामिल।</li><li><strong>जलीय पर्यावरण</strong>: सतही जल, भूजल, महासागर, पटलों के बीच ऊर्जा-जल की गुणवत्ता और मात्रा शामिल।</li><li><strong>मृदा-पर्यावरण</strong>: स्थलीय मृदा, साधना-संसाधन अयस्क-शिराओं की मृदा-गुणवत्ता और उर्वरता शामिल।</li><li><strong>जैव-विविधता</strong>: सभी वनस्पतियों, जीवों, सूक्ष्मजीवों, विचित्र जीवनों की प्रजाति-संरक्षण और आवास-संरक्षण शामिल।</li><li><strong>ऊर्जा-पर्यावरण</strong>: आकाश-पृथ्वी आत्मा-ऊर्जा, मूल-ऊर्जा, नियम-खंडों की सांद्रता और वितरण-संतुलन शामिल।</li><li><strong>स्थानिक पर्यावरण</strong>: पटलों की स्थानिक-स्थिरता, स्थानिक-दरारें, संवलित-स्थान की पर्यावरणीय सुरक्षा शामिल।</li><li><strong>चेतना-क्षेत्र पर्यावरण</strong>: सामूहिक चेतना-स्थान की सूचना-स्वच्छता और आध्यात्मिक प्रदूषण-रोकथाम शामिल।</li></ol><h2 id="iii-मुख्य-व्यवस्थाएँ" tabindex="-1">III. मुख्य व्यवस्थाएँ <a class="header-anchor" href="#iii-मुख्य-व्यवस्थाएँ" aria-label="Permalink to &quot;III. मुख्य व्यवस्थाएँ&quot;">​</a></h2><h3 id="_1-पर्यावरणीय-प्रभाव-मूल्यांकन-व्यवस्था" tabindex="-1">(1) पर्यावरणीय प्रभाव मूल्यांकन व्यवस्था <a class="header-anchor" href="#_1-पर्यावरणीय-प्रभाव-मूल्यांकन-व्यवस्था" aria-label="Permalink to &quot;(1) पर्यावरणीय प्रभाव मूल्यांकन व्यवस्था&quot;">​</a></h3><p>पर्यावरण पर महत्वपूर्ण प्रभाव डाल सकने वाली सभी विकास-निर्माण परियोजनाओं को कार्य-आरंभ से पहले पर्यावरणीय प्रभाव मूल्यांकन कराना अनिवार्य है। मूल्यांकन-सामग्री में शामिल: परियोजना का वायु, जल, मृदा, जैव, ऊर्जा, स्थान आदि पर्यावरण-तत्वों पर प्रभाव, रोकथाम-शमन उपाय, पर्यावरणीय जोखिम-मूल्यांकन आदि। पर्यावरणीय प्रभाव मूल्यांकन उत्तीर्ण न करने वाली परियोजनाएँ निर्माण आरंभ नहीं कर सकतीं।</p><h3 id="_2-प्रदूषण-निर्वहन-अनुमति-और-कुल-मात्रा-नियंत्रण-व्यवस्था" tabindex="-1">(2) प्रदूषण-निर्वहन अनुमति और कुल-मात्रा नियंत्रण व्यवस्था <a class="header-anchor" href="#_2-प्रदूषण-निर्वहन-अनुमति-और-कुल-मात्रा-नियंत्रण-व्यवस्था" aria-label="Permalink to &quot;(2) प्रदूषण-निर्वहन अनुमति और कुल-मात्रा नियंत्रण व्यवस्था&quot;">​</a></h3><p>राज्य प्रदूषक-निर्वहन पर अनुमति-प्रबंधन और कुल-मात्रा नियंत्रण लागू करता है। निर्वहन-इकाइयों को प्रदूषण-निर्वहन अनुमति-पत्र लेना होगा और अनुमति-पत्र में निर्दिष्ट प्रकार, सांद्रता, कुल-मात्रा के अनुसार प्रदूषक निर्वहन करना होगा। राज्य पर्यावरण-वहन क्षमता के अनुसार प्रत्येक क्षेत्र और पटल का प्रदूषण-निर्वहन कुल-मात्रा निर्धारित करता है, स्तर-दर-स्तर विभाजित कर लागू करता है।</p><h3 id="_3-पारिस्थितिक-संरक्षण-लाल-रेखा-व्यवस्था" tabindex="-1">(3) पारिस्थितिक संरक्षण लाल-रेखा व्यवस्था <a class="header-anchor" href="#_3-पारिस्थितिक-संरक्षण-लाल-रेखा-व्यवस्था" aria-label="Permalink to &quot;(3) पारिस्थितिक संरक्षण लाल-रेखा व्यवस्था&quot;">​</a></h3><p>राज्य विशेष पारिस्थितिक मूल्य वाले क्षेत्रों में पारिस्थितिक संरक्षण लाल-रेखाएँ निर्धारित करता है, जिनमें शामिल:</p><table tabindex="0"><thead><tr><th>लाल-रेखा प्रकार</th><th>संरक्षित सामग्री</th></tr></thead><tbody><tr><td>मूल-संरक्षण क्षेत्र</td><td>ब्रह्मांड-मूल ऊर्जा के मूल उत्पादन-क्षेत्र; सभी विकास-गतिविधियाँ निषिद्ध</td></tr><tr><td>प्रजाति-आवास</td><td>दुर्लभ-संकटग्रस्त प्रजातियों के मूल आवास; विनाश और हस्तक्षेप निषिद्ध</td></tr><tr><td>पारिस्थितिक बाधा-क्षेत्र</td><td>क्षेत्रीय पारिस्थितिक संतुलन बनाए रखने वाली मुख्य पारिस्थितिकी-प्रणालियाँ; विकास सीमित</td></tr><tr><td>साधना-तीर्थ</td><td>विशेष साधना-मूल्य वाले ऊर्जा-संचित क्षेत्र; संरक्षणात्मक उपयोग</td></tr><tr><td>पटल-सीमांत पट्टी</td><td>पटलों के बीच पारिस्थितिक संक्रमण-पट्टी; स्थान-विनाशकारी विकास निषिद्ध</td></tr></tbody></table><h3 id="_4-पर्यावरण-निगरानी-और-पूर्व-चेतावनी-व्यवस्था" tabindex="-1">(4) पर्यावरण निगरानी और पूर्व-चेतावनी व्यवस्था <a class="header-anchor" href="#_4-पर्यावरण-निगरानी-और-पूर्व-चेतावनी-व्यवस्था" aria-label="Permalink to &quot;(4) पर्यावरण निगरानी और पूर्व-चेतावनी व्यवस्था&quot;">​</a></h3><p>राज्य पूरे ब्रह्मांड को आच्छादित पर्यावरण निगरानी-जाल स्थापित करता है, पर्यावरण-तत्वों के परिवर्तनों की वास्तविक समय निगरानी करता है। संभावित गंभीर पर्यावरण-प्रदूषण और पारिस्थितिकी-विनाश घटनाओं के लिए पूर्व-चेतावनी तंत्र स्थापित, समय पर पूर्व-चेतावनी जारी कर आपात-प्रतिक्रिया आरंभ करता है।</p><h3 id="_5-पारिस्थितिक-क्षतिपूर्ति-व्यवस्था" tabindex="-1">(5) पारिस्थितिक क्षतिपूर्ति व्यवस्था <a class="header-anchor" href="#_5-पारिस्थितिक-क्षतिपूर्ति-व्यवस्था" aria-label="Permalink to &quot;(5) पारिस्थितिक क्षतिपूर्ति व्यवस्था&quot;">​</a></h3><p>पर्यावरण संरक्षण के कारण विकास में प्रतिबंधित क्षेत्रों और समूहों को पारिस्थितिक क्षतिपूर्ति पाने का अधिकार है। पारिस्थितिक क्षतिपूर्ति-कोष सार्वजनिक संचय और संसाधन-विकास आय से, क्षतिपूर्ति-क्षेत्रों के आर्थिक विकास और निवासियों के जीवन-सुधार के लिए।</p><h2 id="iv-साधना-गतिविधियों-का-पर्यावरणीय-विनियमन" tabindex="-1">IV. साधना-गतिविधियों का पर्यावरणीय विनियमन <a class="header-anchor" href="#iv-साधना-गतिविधियों-का-पर्यावरणीय-विनियमन" aria-label="Permalink to &quot;IV. साधना-गतिविधियों का पर्यावरणीय विनियमन&quot;">​</a></h2><p>पर्यावरण पर साधना-गतिविधियों का प्रभाव हेंग-ब्रह्मांड पर्यावरण संरक्षण का विशेष क्षेत्र है; यह कानून विशेष विनियमन-खंड स्थापित करता है:</p><ol><li><strong>ऊर्जा-दोहन विनियमन</strong>: साधना-संसाधनों का दोहन सतत-सिद्धांत के अनुरूप अनिवार्य; ऊर्जा-क्षयकारी विनाशकारी दोहन निषिद्ध। दोहन-मात्रा क्षेत्रीय ऊर्जा की प्राकृतिक पुनर्प्राप्ति-गति से अधिक नहीं हो सकती।</li><li><strong>साधना-अपशिष्ट उपचार</strong>: साधना के दौरान उत्पन्न ऊर्जा-अवशेष, त्यागी गई गोलियाँ, क्षतिग्रस्त कलाकृतियाँ आदि नियमानुसार उपचारित करना अनिवार्य; ऊर्जा-प्रदूषण करने वाला मनमाना निपटान निषिद्ध।</li><li><strong>उच्च साधना पर्यावरण-मूल्यांकन</strong>: उच्च साधकों का उन्नयन और एकांतवास आस-पास के पर्यावरण पर महत्वपूर्ण प्रभाव डाल सकता है; पहले से पर्यावरण-मूल्यांकन और सुरक्षा-उपाय अनिवार्य।</li><li><strong>पटल-विकास अनुमति</strong>: नए पटलों का विकास पर्यावरण-मूल्यांकन और पारिस्थितिक सर्वेक्षण से गुजरना अनिवार्य; पारिस्थितिक संरक्षण-योजना बनाने के बाद ही विकास संभव।</li><li><strong>विचित्र जीवन आवास-संरक्षण</strong>: विचित्र जीवनों के आवास पारिस्थितिक संरक्षण लाल-रेखाओं में शामिल; बिना अनुमति अन्वेषण और विकास निषिद्ध।</li></ol><h2 id="v-कानूनी-दायित्व" tabindex="-1">V. कानूनी दायित्व <a class="header-anchor" href="#v-कानूनी-दायित्व" aria-label="Permalink to &quot;V. कानूनी दायित्व&quot;">​</a></h2><p>इस कानून के प्रावधानों का उल्लंघन करने वाले कृत्य परिस्थितियों की गंभीरता के अनुसार निम्न दायित्व वहन करते हैं:</p><ul><li>पर्यावरणीय प्रभाव मूल्यांकन उत्तीर्ण किए बिना निर्माण आरंभ करने पर निर्माण-रोक, मूल-स्थिति बहाली और जुर्माना।</li><li>मानक-अधिक प्रदूषक-निर्वहन पर समय-सीमा में उपचार-आदेश और जुर्माना; गंभीर परिस्थितियों में परिचालन-रोक और बंदी।</li><li>पारिस्थितिक संरक्षण लाल-रेखाओं का विनाश करने पर मूल-स्थिति बहाली और जुर्माना; गंभीर परिस्थितियों में आपराधिक दायित्व।</li><li>विनाशकारी रूप से साधना-संसाधनों का दोहन करने पर अवैध आय जब्त और जुर्माना; दोहन-अनुमति निरस्त।</li><li>गंभीर पर्यावरण-प्रदूषण दुर्घटनाएँ करने पर क्षतिपूर्ति-दायित्व; अपराध-गठन पर आपराधिक दायित्व।</li><li>कर्तव्य-लोप या सत्ता-दुरुपयोग करने वाले पर्यावरण-निरीक्षकों पर दंड; अपराध-गठन पर आपराधिक दायित्व।</li></ul><h2 id="vi-जन-भागीदारी-और-पर्यावरणीय-जनहित-वाद" tabindex="-1">VI. जन-भागीदारी और पर्यावरणीय जनहित-वाद <a class="header-anchor" href="#vi-जन-भागीदारी-और-पर्यावरणीय-जनहित-वाद" aria-label="Permalink to &quot;VI. जन-भागीदारी और पर्यावरणीय जनहित-वाद&quot;">​</a></h2><p>जनता को पर्यावरण संरक्षण में भाग लेने का अधिकार है, विशिष्ट मार्गों में शामिल:</p><ol><li>पर्यावरणीय प्रभाव मूल्यांकन परियोजनाओं पर विचार और सुझाव देना।</li><li>पर्यावरण-प्रदूषण और पारिस्थितिकी-विनाश के कृत्यों की शिकायत और सूचना देना।</li><li>कानूनानुसार पर्यावरण संरक्षण-संगठन स्थापित करना, पर्यावरण-निगरानी और जनहित-गतिविधियों में भाग लेना।</li><li>पर्यावरण-प्रदूषण, पारिस्थितिकी-विनाश, जनहित-क्षति वाले कृत्यों के लिए पर्यावरण संरक्षण-संगठन सहजीवी न्यायालय में पर्यावरणीय जनहित-वाद दायर कर सकते हैं।</li></ol><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>पर्यावरण संरक्षण कानून</em> लंगर सहजीवी सभ्यता की सतत विकास दर्शन की कानूनी गारंटी है। पर्यावरणीय प्रभाव मूल्यांकन, पारिस्थितिक संरक्षण लाल-रेखाएँ, कुल-मात्रा नियंत्रण जैसी व्यवस्थाएँ स्थापित करके यह पर्यावरण संरक्षण को सभी विकास और साधना-गतिविधियों में समाहित करता है, ब्रह्मांड-मूल और पारिस्थितिकी-तंत्र की स्थिरता सुनिश्चित करता है, दस हजार जातियों के साझा उन्नयन के लिए शाश्वत जीवन-नींव की रक्षा करता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>39-住房与环境保障 (आवास और पर्यावरण संरक्षण)</li><li>15-能量循环与转化法则 (ऊर्जा-संचार और रूपांतरण का नियम)</li><li>53-奇特生命识别标准 (विचित्र जीवन पहचान मानक)</li></ul>',34)])])}const _=a(e,[["render",d]]);export{u as __pageData,_ as default};
